// src/pages/OtherProfile.js

import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { FiSettings } from "react-icons/fi";

function OtherProfile() {
  const navigate = useNavigate();
  const location = useLocation();
  const userName = location.state?.user || "민지";
  const [isFollowing, setIsFollowing] = useState(false);

  const userData = {
    민지: {
      followers: 23, following: 15,
      books: [
        { title: "노르웨이의 숲", review: "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다." },
        { title: "데미안", review: "자기 자신을 찾아가는 과정이 정말 인상 깊었다." },
        { title: "어린왕자", review: "순수함에 대해 다시 생각하게 만든 책이었다." },
      ],
    },
    현우: {
      followers: 31, following: 20,
      books: [
        { title: "1984", review: "감시 사회의 무서움을 현실적으로 보여줬다." },
        { title: "데미안", review: "성장이란 결국 자신을 마주하는 과정이었다." },
      ],
    },
    서연: {
      followers: 18, following: 9,
      books: [
        { title: "채식주의자", review: "강렬하면서도 오래 기억에 남는 작품이었다." },
        { title: "해변의 카프카", review: "현실과 환상이 섞인 분위기가 좋았다." },
      ],
    },
  };

  const profile = userData[userName] || userData["민지"];

  return (
    <div className="page">

      {/* 상단 */}
      <div className="profile-header">
        <div className="logo">READLY</div>
        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}
      <div className="profile-top">
        <div className="profile-image"></div>
        <div className="profile-info">
          <div className="profile-name">{userName} 📚</div>
          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">{profile.followers}</div>
              <div className="follow-text">팔로워</div>
            </div>
            <div className="follow-box">
              <div className="follow-num">{profile.following}</div>
              <div className="follow-text">팔로잉</div>
            </div>
          </div>
          <button
            className={isFollowing ? "following-btn" : "follow-btn"}
            onClick={() => setIsFollowing(!isFollowing)}
          >
            {isFollowing ? "팔로잉" : "팔로우"}
          </button>
        </div>
      </div>

      {/* 소개 */}
      <div className="profile-desc">
        함께 책 읽고 이야기하는 걸 좋아해요 📖
      </div>

      <div className="line"></div>

      {/* 베이지 배경 */}
      <div style={{
        position: "fixed",
        top: "280px",
        bottom: "72px",
        left: "50%",
        transform: "translateX(-50%)",
        width: "100%",
        maxWidth: "430px",
        background: `
          radial-gradient(ellipse at 80% 0%, rgba(255,220,120,0.18) 0%, transparent 60%),
          repeating-linear-gradient(90deg, transparent, transparent 39px, rgba(180,140,90,0.07) 39px, rgba(180,140,90,0.07) 40px),
          repeating-linear-gradient(180deg, transparent, transparent 39px, rgba(180,140,90,0.07) 39px, rgba(180,140,90,0.07) 40px),
          #f5ede0
        `,
        zIndex: 40,
      }} />

      {/* 조명 + 책 + 선반 */}
      <div style={{
        position: "fixed",
        bottom: "72px",
        left: "50%",
        transform: "translateX(-50%)",
        width: "100%",
        maxWidth: "430px",
        padding: "0 20px",
        zIndex: 50,
      }}>

        {/* 조명 */}
        <div style={{ position: "absolute", top: -50, right: 40, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div style={{ width: "2px", height: "28px", background: "#b89060" }} />
          <div style={{ width: "44px", height: "20px", background: "#c9a055", borderRadius: "0 0 22px 22px", position: "relative" }}>
            <div style={{
              position: "absolute", bottom: "-40px", left: "50%", transform: "translateX(-50%)",
              width: "120px", height: "60px",
              background: "radial-gradient(ellipse, rgba(255,210,80,0.22) 0%, transparent 70%)",
              pointerEvents: "none",
            }} />
          </div>
        </div>

        {/* 책들 */}
        <div style={{ display: "flex", alignItems: "flex-end", gap: "0px", overflowX: "auto", padding: "0 4px" }}>
          {profile.books.map((book, index) => {
            const heights = [180, 220, 160, 200, 175, 215, 165, 190];
            const colors = ["#7bc142", "#a8d84e", "#5aab35", "#c5e87a", "#68b83e", "#b2de5f", "#4e9e2f", "#d4f09a"];
            const h = heights[index % heights.length];
            const bg = colors[index % colors.length];

            return (
              <div
                key={index}
                style={{ flexShrink: 0, cursor: "pointer", transition: "transform 0.15s" }}
                onMouseEnter={e => e.currentTarget.style.transform = "translateY(-6px)"}
                onMouseLeave={e => e.currentTarget.style.transform = "translateY(0)"}
                onClick={() => navigate("/review", { state: { title: book.title, review: book.review } })}
              >
                <div style={{
                  width: "48px", height: `${h}px`, background: bg,
                  borderRadius: "5px 5px 0 0",
                  display: "flex", justifyContent: "center", alignItems: "center",
                  color: "rgba(0,0,0,0.22)", fontSize: "11px", fontWeight: "700",
                  writingMode: "vertical-rl", textOrientation: "mixed",
                  overflow: "hidden", padding: "10px 0",
                }}>
                  {book.title}
                </div>
              </div>
            );
          })}
        </div>

        {/* 나무 선반 */}
        <div style={{
          height: "14px",
          background: "linear-gradient(to bottom, #c8974a, #a87840)",
          borderRadius: "3px",
          boxShadow: "0 3px 8px rgba(120,80,30,0.18)",
        }} />
      </div>

    </div>
  );
}

export default OtherProfile;
